import{_ as a,o as r,c as o,a2 as d}from"./chunks/framework.CiKk3sJz.js";const u=JSON.parse('{"title":"漫画 · 第 19 话 拖放 API：松手之前的九条事件","description":"","frontmatter":{},"headers":[],"relativePath":"comics/html/EP.19-drag-drop.md","filePath":"comics/html/EP.19-drag-drop.md","lastUpdated":1792579602000}'),t={name:"comics/html/EP.19-drag-drop.md"};function l(i,e,n,c,s,p){return r(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="漫画-·-第-19-话-拖放-api-松手之前的九条事件" tabindex="-1">漫画 · 第 19 话 拖放 API：松手之前的九条事件 <a class="header-anchor" href="#漫画-·-第-19-话-拖放-api-松手之前的九条事件" aria-label="Permalink to &quot;漫画 · 第 19 话 拖放 API：松手之前的九条事件&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/html/08-drag-drop">docs/html/08-drag-drop.md</a> ｜ 原画：<a href="./EP.19-drag-drop.svg">EP.19-drag-drop.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，用 mousedown + mousemove 手搓看板拖拽，自己管状态、算边界、做幽灵元素；产品又要求&quot;从桌面把图片拖进浏览器上传&quot;——这是鼠标模拟无论如何做不到的。</li><li><strong>标签君</strong>：HTML5 结构师，本话主角。给卡片加 <code>draggable=&quot;true&quot;</code>，演示浏览器原生的拖拽影像、命中判定与系统级数据通道。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>HTML5 Drag and Drop 是浏览器内置的拖放框架：一个 <code>draggable</code> 属性 + 九个 drag 事件 + <code>dataTransfer</code> 数据桥。浏览器负责拖拽影像（被拖元素的半透明快照）、命中判定和与操作系统的数据通道（连桌面文件都能拖进来），开发者只声明&quot;谁能拖、谁能收、收下干什么&quot;。代价是事件流反直觉，且移动端全线不支持。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>鼠标事件模拟拖拽要自己管理拖拽状态、边界计算、命中测试、幽灵元素，触摸端还得重来一遍；而从操作系统拖文件进网页（<code>DataTransfer.files</code>）受 OS 级限制，JS 模拟根本不可能。看板流转、列表排序、附件上传这类高频交互值得用原生能力。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>拖拽生命周期分两端九个事件：源上 <code>dragstart → drag（高频）→ dragend</code>；目标上 <code>dragenter → dragover（高频）→ drop</code>，不投放而离开则 <code>dragleave</code>。三条铁律：①<strong>dragover 必须 <code>preventDefault()</code></strong>——浏览器默认禁止投放，只有放行才等于声明&quot;此处可收&quot;，少了这行 drop 永远不触发、松手直接回弹；②drop 里通常也要 preventDefault，阻止打开链接等默认行为；③数据只能在 dragstart 用 <code>setData</code> 写、drop 用 <code>getData</code> 读，dragover 阶段出于安全只能读 <code>types</code> 列表。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>排序精髓：dragover 高频回调里用 <code>getBoundingClientRect()</code> 比较各兄弟卡片几何中心与指针的位置，找到&quot;该插到谁前面&quot;，直接 <code>insertBefore</code> 移动真实元素（比拖完再排更流畅）；drop 事件委托在容器上监听，避免落在子元素上。文件拖入：dragover 放行后，drop 里读 <code>e.dataTransfer.files</code>，检查 <code>file.type</code> 再用 FileReader 读 data URL 预览；<code>setDragImage()</code> 可换自定义影像。移动端安卓全线不支持 drag 事件，标准替代是 Pointer Events：<code>pointerdown</code> 时 <code>setPointerCapture</code>，pointermove 跟幽灵元素 + <code>elementFromPoint</code> 找投放区，pointerup 触发业务——把&quot;落点后干什么&quot;抽成独立函数，两条路径复用。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>draggable=true 才是源；dragover 不 preventDefault，drop 永远不触发——DnD 第一大坑。</li><li>dataTransfer 是一次性信封：dragstart 写、drop 读，中途只许看 types；files 走系统级通道。</li><li>排序在 dragover 里算中心点 insertBefore；移动端不支持原生 DnD，用 Pointer Events 复用同一业务。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：投放区监听了 drop 并写好了上传逻辑，但松手时卡片总是弹回原位、drop 回调一次都不进，最可能漏了什么？为什么浏览器要这样设计？</p><p><strong>答</strong>：漏了在投放区的 <code>dragover</code>（以及通常 <code>dragenter</code>）事件里调用 <code>e.preventDefault()</code>。浏览器默认把&quot;向页面投放内容&quot;视为危险动作并一律禁止——防止用户误把桌面文件、链接拖进网页触发意外导航或上传；开发者必须在 dragover 上显式放行，浏览器才认为这个元素&quot;愿意接收投放&quot;，drop 事件才会在松手时派发。所以最小可用投放区永远是一对处理器：<code>dragover</code> 里 preventDefault（可顺带设 <code>dropEffect</code>），<code>drop</code> 里再 preventDefault 并读取 <code>dataTransfer</code> 执行业务。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>事件流日志 + setData/getData + effectAllowed/dropEffect + 自定义影像：<a href="./../../examples/html/08-drag-drop/index-01-drag-events-basics.html">examples/html/08-drag-drop/index-01-drag-events-basics.html</a></li><li>拖拽排序列表 + 三列看板跨容器流转：<a href="./../../examples/html/08-drag-drop/index-02-sortable-kanban.html">index-02-sortable-kanban.html</a></li><li>DataTransfer.files 文件拖放 + FileReader 图片预览：<a href="./../../examples/html/08-drag-drop/index-03-file-drop-preview.html">index-03-file-drop-preview.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 20 话《多媒体》——不用插件的播放器：source 格式回退、自动播放策略、字幕轨道与 picture 响应式决策。</p>',22)])])}const g=a(t,[["render",l]]);export{u as __pageData,g as default};
